import{_ as t,o as n,c as r,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"State of CephFS- Three Easy Pieces - Venky Shankar, IBM & Patrick Donnelly, IBM, Inc.","description":"","frontmatter":{"title":"State of CephFS- Three Easy Pieces - Venky Shankar, IBM & Patrick Donnelly, IBM, Inc.","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["CephFS","Distributed File System","Ceph Storage","Storage Optimization","POSIX Compliance"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/State_of_CephFS_-_Three_Easy_Pieces_-_Venky_Shankar_IBM_Patrick_Donnelly_IBM_Inc..md","filePath":"posts/2025/State_of_CephFS_-_Three_Easy_Pieces_-_Venky_Shankar_IBM_Patrick_Donnelly_IBM_Inc..md","lastUpdated":1780459816000}'),o={name:"posts/2025/State_of_CephFS_-_Three_Easy_Pieces_-_Venky_Shankar_IBM_Patrick_Donnelly_IBM_Inc..md"};function i(s,e,l,S,_,g){return n(),r("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要-cephfs-三部曲" tabindex="-1">会议纪要：CephFS 三部曲 <a class="header-anchor" href="#会议纪要-cephfs-三部曲" aria-label="Permalink to &quot;会议纪要：CephFS 三部曲&quot;">​</a></h3><p><strong>会议主题</strong>: CephFS (SFS) 三部曲 <strong>主讲人</strong>: Venki、Patrick、RI <strong>会议时间</strong>: 未知 <strong>会议地点</strong>: 线上/线下</p><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议主要讨论了 CephFS（SFS）的最新进展、历史回顾以及未来发展方向。会议分为三个部分：SFS 概述、SFS 的最新功能和改进、以及未来的工作计划。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>SFS 概述</strong></p><ul><li><strong>SFS 简介</strong>: SFS 是一个 POSIX 兼容的分布式文件系统，旨在提供与本地文件系统相同的用户体验。SFS 通过分离元数据和数据处理，元数据由 MDS (Metadata Server) 处理，而客户端直接与数据池交互进行读写操作。</li><li><strong>历史回顾</strong>: SFS 自 2006 年首次提出以来，经历了多个重要阶段，包括 2014 年被 Red Hat 收购，2016 年宣布稳定，2017 年引入多 MDS 支持等。</li></ul></li><li><p><strong>SFS 的最新功能和改进</strong></p><ul><li><strong>Qui 功能</strong>: 该功能支持崩溃一致性快照，允许在多个目录上进行一致性快照操作，特别适用于分布式数据库等场景。</li><li><strong>MDS Journal 修剪改进</strong>: 优化了 MDS 日志修剪机制，减少了线程锁争用问题，提升了性能。</li><li><strong>自动平衡器</strong>: 默认禁用了自动平衡器，以避免在多 MDS 集群中出现子树分裂过多导致的性能问题。</li><li><strong>Case-insensitive 目录树</strong>: 为支持 Samba 环境，引入了大小写不敏感的目录树功能，提升了性能。</li><li><strong>高效硬链接管理</strong>: 通过引入 Referent Inode，解决了全局快照域（Global Snap Realm）在硬链接管理中的性能和稳定性问题。</li><li><strong>FS Crypt 支持</strong>: 在 Linux 6.6 内核中，SFS 支持了 FS Crypt 加密功能，用户可以通过 fs-crypt 工具加密 SFS 目录树。</li><li><strong>异步 I/O 支持</strong>: 用户空间客户端和 NFS Ganesha 的异步 I/O 支持，提升了 I/O 吞吐量。</li></ul></li><li><p><strong>未来的工作计划</strong></p><ul><li><strong>Referent Inode 的进一步优化</strong>: 该功能预计在 Tentacle 版本中发布，旨在彻底解决硬链接管理中的性能问题。</li><li><strong>快速克隆 (Fast Cloning)</strong>: 基于 Referent Inode 的工作，未来将实现类似 RBD 的快速克隆功能，避免全量复制。</li><li><strong>QoS (Quality of Service)</strong>: 计划在未来的版本中引入 QoS 支持，以更好地管理存储资源。</li><li><strong>用户空间 FS Crypt 支持</strong>: 正在开发用户空间 FS Crypt 支持，预计在 Tentacle 版本中发布。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>Qui 功能</strong>：已实现并将在 Squid 版本中发布，支持崩溃一致性快照。</li><li><strong>自动平衡器</strong>：默认禁用，以避免性能问题。</li><li><strong>Case-insensitive 目录树</strong>：预计在 Tentacle 版本中发布，支持 Samba 环境。</li><li><strong>Referent Inode</strong>：预计在 Tentacle 版本中发布，解决硬链接管理中的性能问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>继续优化 MDS 性能</strong>：进一步改进 MDS 的日志修剪和子树管理。</li><li><strong>开发快速克隆功能</strong>：基于 Referent Inode 的工作，实现快速克隆。</li><li><strong>引入 QoS 支持</strong>：计划在未来的版本中引入 QoS，以更好地管理存储资源。</li><li><strong>用户空间 FS Crypt 支持</strong>：继续开发用户空间 FS Crypt 功能，确保与内核版本的兼容性。</li></ul><h4 id="问答环节" tabindex="-1">问答环节 <a class="header-anchor" href="#问答环节" aria-label="Permalink to &quot;问答环节&quot;">​</a></h4><ul><li><strong>FS Crypt 与 Case-insensitive 目录树的兼容性</strong>：FS Crypt 的加密名称将作为 Alternate Name，确保大小写不敏感的目录树功能正常工作。</li><li><strong>客户端是否会被通知 Qui 操作</strong>：客户端不会被直接通知 Qui 操作，但会收到 caps 召回通知。</li><li><strong>SFS Mirror 是否支持同步扩展属性</strong>：目前不支持，但有计划在未来版本中解决。</li></ul><p><strong>会议总结</strong>: 本次会议详细介绍了 CephFS 的最新进展和未来计划，特别是在性能优化、硬链接管理、加密支持等方面。未来将继续优化 MDS 性能，并引入快速克隆和 QoS 支持，以满足更多用户需求。</p>',13)])])}const c=t(o,[["render",i]]);export{p as __pageData,c as default};
